-- RPC: Get My Children Profiles (For Parents)
-- Logic: Finds admission applications linked to this parent (by email or phone usually, but here we might need a simpler link for now).
-- Since we don't have a reliable email link in the admissions table for 'parent_user_id' yet, we'll rely on a direct link or fallback to email matching (weak link) or a junction table. for now, let's assume 'parent_email' matches 'email' in profiles.
-- BETTER: We should rely on `admissions` having a `parent_id` if we want strict linking.
-- FOR NOW: We will use the `parent_email` from `admissions` matching the `email` of the logged-in parent.

DROP FUNCTION IF EXISTS public.get_my_children_profiles() CASCADE;
CREATE OR REPLACE FUNCTION public.get_my_children_profiles()
RETURNS TABLE (
    id UUID,
    applicant_name TEXT,
    grade TEXT,
    status TEXT,
    profile_photo_url TEXT,
    date_of_birth DATE,
    gender TEXT,
    medical_info TEXT,
    emergency_contact TEXT,
    student_user_id UUID,
    parent_email TEXT
) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY
    SELECT 
        a.id,
        a.applicant_name,
        a.grade,
        a.status,
        a.profile_photo_url,
        a.date_of_birth,
        a.gender,
        a.medical_info,
        a.emergency_contact,
        a.student_user_id,
        a.parent_email
    FROM public.admissions a
    WHERE a.parent_id = auth.uid()
       OR a.parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid())
    ORDER BY a.submitted_at DESC;
END;
$$;

-- RPC: Artifact Vault Synchronization Logic
DROP FUNCTION IF EXISTS public.parent_initialize_vault_slots_all() CASCADE;
CREATE OR REPLACE FUNCTION public.parent_initialize_vault_slots_all()
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_admission RECORD;
    v_doc_name TEXT;
    v_mandatory_docs TEXT[] := ARRAY['Birth Certificate', 'Identity Proof', 'Medical Report', 'Previous Transcript'];
BEGIN
    FOR v_admission IN 
        SELECT id FROM public.admissions 
        WHERE parent_id = auth.uid() 
           OR parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid()) 
    LOOP
        FOR v_doc_name IN SELECT unnest(v_mandatory_docs) LOOP
            IF NOT EXISTS (SELECT 1 FROM public.document_requirements WHERE admission_id = v_admission.id AND document_name = v_doc_name) THEN
                INSERT INTO public.document_requirements (admission_id, document_name, is_mandatory, status)
                VALUES (v_admission.id, v_doc_name, true, 'Pending');
            END IF;
        END LOOP;
    END LOOP;
END;
$$;

DROP FUNCTION IF EXISTS public.parent_get_document_requirements(UUID) CASCADE;
CREATE OR REPLACE FUNCTION public.parent_get_document_requirements(p_user_id UUID)
RETURNS SETOF JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY
    SELECT row_to_json(r)::jsonb
    FROM (
        SELECT 
            dr.*,
            (
                SELECT jsonb_agg(ad)
                FROM (
                    SELECT * FROM public.admission_documents 
                    WHERE admission_id = dr.admission_id 
                    AND document_name = dr.document_name
                    ORDER BY uploaded_at DESC
                ) ad
            ) as admission_documents
        FROM public.document_requirements dr
        JOIN public.admissions a ON dr.admission_id = a.id
        WHERE a.parent_id = p_user_id 
           OR a.parent_email = (SELECT email FROM public.profiles WHERE profiles.id = p_user_id)
    ) r;
END;
$$;

DROP FUNCTION IF EXISTS public.parent_complete_document_upload(BIGINT, UUID, TEXT, TEXT, BIGINT, TEXT) CASCADE;
CREATE OR REPLACE FUNCTION public.parent_complete_document_upload(
    p_requirement_id BIGINT,
    p_admission_id UUID,
    p_file_name TEXT,
    p_storage_path TEXT,
    p_file_size BIGINT,
    p_mime_type TEXT
) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    -- Insert doc record
    INSERT INTO public.admission_documents (
        admission_id, 
        document_name, 
        file_name,
        storage_path, 
        file_size,
        mime_type,
        status
    ) 
    SELECT 
        p_admission_id, 
        document_name, 
        p_file_name,
        p_storage_path, 
        p_file_size,
        p_mime_type,
        'Submitted'
    FROM public.document_requirements 
    WHERE id = p_requirement_id;

    -- Update requirement status
    UPDATE public.document_requirements 
    SET status = 'Submitted' 
    WHERE id = p_requirement_id;
END;
$$;

-- RPC: Generate Admission Share Code
DROP FUNCTION IF EXISTS public.generate_admission_share_code(UUID, TEXT, TEXT) CASCADE;

CREATE OR REPLACE FUNCTION public.generate_admission_share_code(
    p_admission_id UUID,
    p_code_type TEXT,
    p_purpose TEXT
) RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_code TEXT;
    v_parent_id UUID;
BEGIN
    -- Ownership Check
    SELECT parent_id INTO v_parent_id FROM public.admissions WHERE id = p_admission_id;
    
    IF v_parent_id IS NULL OR v_parent_id <> auth.uid() THEN
        -- Check if current user is the parent via email fallback
        IF NOT EXISTS (
            SELECT 1 FROM public.admissions a
            JOIN public.profiles p ON p.email = a.parent_email
            WHERE a.id = p_admission_id AND p.id = auth.uid()
        ) THEN
            RAISE EXCEPTION 'Access Denied: Node ownership verification failed.';
        END IF;
    END IF;

    -- Generate random 6-char alphanumeric code
    v_code := upper(substr(md5(random()::text), 1, 6));

    INSERT INTO public.share_codes (
        code, 
        admission_id, 
        code_type, 
        purpose, 
        expires_at, 
        created_by
    ) VALUES (
        v_code, 
        p_admission_id, 
        p_code_type, 
        p_purpose, 
        NOW() + INTERVAL '24 hours',
        auth.uid()
    );

    RETURN v_code;
END;
$$;

-- RPC: Revoke My Share Code
DROP FUNCTION IF EXISTS public.revoke_my_share_code(BIGINT) CASCADE;

CREATE OR REPLACE FUNCTION public.revoke_my_share_code(p_code_id BIGINT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    UPDATE public.share_codes 
    SET status = 'Revoked'
    WHERE id = p_code_id 
    AND (
        created_by = auth.uid()
        OR EXISTS (
            SELECT 1 FROM public.admissions a
            WHERE a.id = share_codes.admission_id
            AND (a.parent_id = auth.uid() OR a.parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid()))
        )
    );
END;
$$;

