-- RPC: Get Student Dashboard Data
CREATE OR REPLACE FUNCTION public.get_student_dashboard_data(p_student_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_profile RECORD;
    v_admission RECORD;
    v_financials RECORD;
    v_attendance RECORD;
    v_timetable JSONB;
    v_assignments JSONB;
BEGIN
    -- 1. Fetch Basic Identity
    -- Try to find by Admission ID first (Applicant phase) or User ID (Enrolled phase)
    SELECT * INTO v_admission FROM public.admissions WHERE admissions.id = p_student_id OR student_user_id = p_student_id LIMIT 1;
    
    -- If no admission record, try looking up student profile directly
    IF v_admission IS NULL THEN
        SELECT * INTO v_admission FROM public.admissions WHERE student_user_id = p_student_id LIMIT 1;
    END IF;

    -- Fetch Profile data
    SELECT p.*, sp.grade, sp.roll_number, sp.enrollment_status 
    INTO v_profile 
    FROM public.profiles p
    LEFT JOIN public.student_profiles sp ON p.id = sp.user_id
    WHERE p.id = (v_admission.student_user_id) OR p.id = p_student_id;

    -- 2. Fetch Financials
    SELECT 
        COALESCE(SUM(amount) FILTER (WHERE status = 'Pending'), 0) as pending_dues,
        COALESCE(SUM(amount) FILTER (WHERE status = 'Paid'), 0) as paid_amount
    INTO v_financials
    FROM public.fee_invoices
    WHERE student_id = v_profile.id;

    -- 3. Fetch Attendance
    SELECT 
        COUNT(*) FILTER (WHERE status = 'Present') as present_days,
        COUNT(*) FILTER (WHERE status = 'Absent') as absent_days
    INTO v_attendance
    FROM public.attendance_records
    WHERE student_id = v_profile.id;

    -- 4. Construct Result
    RETURN jsonb_build_object(
        'profile', to_jsonb(v_profile),
        'admission', to_jsonb(v_admission),
        'financials', to_jsonb(v_financials),
        'attendance', to_jsonb(v_attendance),
        'needs_onboarding', (v_profile.profile_completed = false)
    );
END;
$$;


