-- RPC: Upsert Teacher Profile
CREATE OR REPLACE FUNCTION public.upsert_teacher_profile(
    p_user_id UUID,
    p_display_name TEXT,
    p_email TEXT,
    p_phone TEXT,
    p_department TEXT,
    p_designation TEXT,
    p_subject TEXT,
    p_qualification TEXT,
    p_experience INT,
    p_doj DATE
) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    -- Update base profile
    UPDATE public.profiles 
    SET display_name = p_display_name, phone = p_phone, profile_completed = true 
    WHERE id = p_user_id;

    -- Upsert teacher details
    INSERT INTO public.teacher_profiles (user_id, subject_specialization, qualification, experience_years, bio, designation, department)
    VALUES (p_user_id, p_subject, p_qualification, p_experience, 'New Teacher', p_designation, p_department)
    ON CONFLICT (user_id) DO UPDATE SET
        subject_specialization = EXCLUDED.subject_specialization,
        qualification = EXCLUDED.qualification,
        experience_years = EXCLUDED.experience_years,
        designation = EXCLUDED.designation,
        department = EXCLUDED.department;
END;
$$;

-- RLS: Enhanced Parent Policies for Admissions
-- 1. SELECT: Parents view their own submissions
CREATE POLICY "Parents select own applications" ON public.admissions
    FOR SELECT USING (
        parent_id = auth.uid() 
        OR parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid())
    );

-- 2. INSERT: Parents can create new applications
CREATE POLICY "Parents insert own applications" ON public.admissions
    FOR INSERT WITH CHECK (
        parent_id = auth.uid()
        OR parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid())
    );

-- 3. UPDATE: Parents can update pending applications
CREATE POLICY "Parents update own applications" ON public.admissions
    FOR UPDATE USING (
        parent_id = auth.uid() 
        OR parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid())
    ) WITH CHECK (
        status IN ('Pending Review', 'Draft', 'ENQUIRY_ACTIVE') -- Only allow updates in early stages
    );

-- RLS: Document Vault Security
ALTER TABLE public.admission_documents ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Parents manage own documents" ON public.admission_documents
    FOR ALL USING (
        EXISTS (
            SELECT 1 FROM public.admissions aa 
            WHERE aa.id = admission_documents.admission_id 
            AND (aa.parent_id = auth.uid() OR aa.parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid()))
        )
    );

-- RLS: Financial Transparency for Parents
CREATE POLICY "Parents view children invoices" ON public.fee_invoices
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.admissions aa 
            WHERE aa.student_user_id = fee_invoices.student_id 
            AND (aa.parent_id = auth.uid() OR aa.parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid()))
        )
    );

CREATE POLICY "Parents view children payments" ON public.fee_payments
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.admissions aa 
            WHERE aa.student_user_id = fee_payments.student_id 
            AND (aa.parent_id = auth.uid() OR aa.parent_email = (SELECT email FROM public.profiles WHERE profiles.id = auth.uid()))
        )
    );

-- RLS: Communication Inbox Access
ALTER TABLE public.communications ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users view relevant communications" ON public.communications
    FOR SELECT USING (
        sender_id = auth.uid()
        OR auth.uid()::text = ANY(recipients)
        -- OR check for role-based broadcast (simplified)
        OR (SELECT role FROM public.profiles WHERE profiles.id = auth.uid()) = ANY(recipients)
    );

-- RLS: Update Student Profile policies
CREATE POLICY "Parents can view their children's profiles" ON public.student_profiles
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.admissions aa 
            WHERE aa.student_user_id = student_profiles.user_id 
            AND (aa.parent_id = auth.uid() OR aa.parent_email = (SELECT email FROM public.profiles WHERE id = auth.uid()))
        )
    );

-- RPC: Switch Active Role (Critical for Role Selection & Identity Provisioning)
-- ===============================================================================================
CREATE OR REPLACE FUNCTION public.switch_active_role(p_target_role TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_profile_exists BOOLEAN := false;
    v_table_name TEXT;
    v_profile_completed BOOLEAN := false;
    v_onboarding_step TEXT := 'profile';
BEGIN
    -- 1. Identify target table based on role to check for existing context
    v_table_name := CASE p_target_role
        WHEN 'School Administration' THEN 'school_admin_profiles'
        WHEN 'Parent/Guardian' THEN 'parent_profiles'
        WHEN 'Student' THEN 'student_profiles'
        WHEN 'Teacher' THEN 'teacher_profiles'
        WHEN 'Accountant' THEN 'staff_profiles'
        WHEN 'HR Manager' THEN 'staff_profiles'
        WHEN 'Academic Coordinator' THEN 'staff_profiles'
        WHEN 'Principal' THEN 'staff_profiles'
        WHEN 'Transport Staff' THEN 'transport_profiles'
        WHEN 'Ecommerce Operator' THEN 'ecommerce_profiles'
        ELSE NULL
    END;

    -- 2. Performance-Aware Restoration Check
    IF v_table_name IS NOT NULL THEN
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE user_id = $1)', v_table_name)
        INTO v_profile_exists
        USING auth.uid();

        -- Special handling for School Admin onboarding state
        IF p_target_role = 'School Administration' AND v_profile_exists THEN
            SELECT onboarding_step INTO v_onboarding_step 
            FROM public.school_admin_profiles 
            WHERE user_id = auth.uid();
            
            v_profile_completed := (v_onboarding_step = 'completed');
        ELSE
            v_profile_completed := v_profile_exists;
        END IF;
    END IF;

    -- 3. Atomic Identity Upgrade
    UPDATE public.profiles 
    SET role = p_target_role,
        profile_completed = v_profile_completed
    WHERE profiles.id = auth.uid();

    -- 4. Secure State Synchronization
    RETURN jsonb_build_object(
        'success', true,
        'profile_restored', v_profile_completed,
        'new_role', p_target_role,
        'onboarding_step', v_onboarding_step,
        'context_table', v_table_name
    );
END;
$$;

