-- RPC: Finalize Enrollment (Core Logic)
DROP FUNCTION IF EXISTS public.admin_finalize_enrollment(UUID) CASCADE;
CREATE OR REPLACE FUNCTION public.admin_finalize_enrollment(p_admission_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_admission RECORD;
    v_student_id UUID;
    v_student_id_number TEXT;
BEGIN
    -- 1. Fetch Application context
    SELECT * INTO v_admission FROM public.admissions WHERE id = p_admission_id;
    IF v_admission IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Application node not found.');
    END IF;

    -- 2. Create Student Identity (Profiles table)
    -- If they don't have a user_id yet (external applicant), we might need to handle that, 
    -- but usually student_user_id is provisioned via Auth or a separate process.
    -- For now, if student_user_id is missing, we create a placeholder ID or return error.
    IF v_admission.student_user_id IS NULL THEN
        -- In a real system, we'd trigger a 'Create Student Account' flow here.
        -- For this simulation, we'll assume the student_user_id exists if they've registered.
        -- If not, we might need a workaround. Let's assume it exists for now.
        RETURN jsonb_build_object('success', false, 'message', 'Student User ID not provisioned. Account required.');
    END IF;

    v_student_id := v_admission.student_user_id;
    v_student_id_number := 'STU-' || v_admission.id::TEXT; -- Simplified

    -- 3. Update Base Profile
    UPDATE public.profiles 
    SET role = 'Student', profile_photo_url = v_admission.profile_photo_url 
    WHERE id = v_student_id;

    -- 4. Create specialized Student Profile
    INSERT INTO public.student_profiles (
        user_id, grade, date_of_birth, gender, branch_id, 
        enrollment_status, student_id_number, emergency_contact, medical_info
    ) VALUES (
        v_student_id, v_admission.grade, v_admission.date_of_birth, v_admission.gender, v_admission.branch_id,
        'Enrolled', v_student_id_number, v_admission.emergency_contact, v_admission.medical_info
    ) ON CONFLICT (user_id) DO UPDATE SET
        enrollment_status = 'Enrolled',
        student_id_number = EXCLUDED.student_id_number;

    -- 5. Finalize Application status
    UPDATE public.admissions SET status = 'Approved' WHERE id = p_admission_id;

    RETURN jsonb_build_object(
        'success', true, 
        'student_id', v_student_id, 
        'student_id_number', v_student_id_number
    );
END;
$$;

-- ===============================================================================================
-- INSTITUTIONAL SETUP & BRANCH HYPER-PROTOCOL
-- ===============================================================================================

-- RPC: Initialize School Admin
CREATE OR REPLACE FUNCTION public.initialize_school_admin()
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    -- Identity provisioning for the global node
    UPDATE public.profiles 
    SET role = 'School Administration', profile_completed = false
    WHERE id = auth.uid();

    -- Context metadata initialization
    INSERT INTO public.school_admin_profiles (user_id, onboarding_step)
    VALUES (auth.uid(), 'profile')
    ON CONFLICT (user_id) DO NOTHING;
END;
$$;

-- RPC: Create School Branch
CREATE OR REPLACE FUNCTION public.create_school_branch(
    p_name TEXT,
    p_address TEXT,
    p_city TEXT,
    p_state TEXT,
    p_country TEXT,
    p_contact_number TEXT,
    p_is_main BOOLEAN,
    p_email TEXT,
    p_admin_name TEXT,
    p_admin_phone TEXT,
    p_admin_email TEXT
) RETURNS SETOF public.school_branches LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_branch_id BIGINT;
BEGIN
    -- Global Singleton Check for Main Branch
    IF p_is_main THEN
        UPDATE public.school_branches SET is_main_branch = false WHERE id IN (SELECT id FROM public.school_branches WHERE is_main_branch = true);
    END IF;

    INSERT INTO public.school_branches (
        name, address, city, state, country, is_main_branch, admin_email, access_key, school_id, status
    ) VALUES (
        p_name, p_address, p_city, p_state, p_country, p_is_main, p_admin_email, 
        upper(substr(md5(random()::text), 1, 8)), auth.uid(), 'Pending'
    ) RETURNING id INTO v_branch_id;

    RETURN QUERY SELECT * FROM public.school_branches WHERE id = v_branch_id;
END;
$$;


-- RPC: Get School Branches
CREATE OR REPLACE FUNCTION public.get_school_branches()
RETURNS SETOF public.school_branches LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT * FROM public.school_branches 
    WHERE school_id = auth.uid()
    ORDER BY is_main_branch DESC, created_at ASC;
END;
$$;

-- RPC: Update School Branch
CREATE OR REPLACE FUNCTION public.update_school_branch(
    p_branch_id BIGINT,
    p_name TEXT,
    p_address TEXT,
    p_city TEXT,
    p_state TEXT,
    p_country TEXT,
    p_contact_number TEXT,
    p_is_main BOOLEAN,
    p_email TEXT,
    p_admin_name TEXT,
    p_admin_phone TEXT,
    p_admin_email TEXT
) RETURNS SETOF public.school_branches LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    -- Synchronization protocol for singleton main branch
    IF p_is_main THEN
        UPDATE public.school_branches SET is_main_branch = false WHERE id <> p_branch_id;
    END IF;

    UPDATE public.school_branches SET
        name = p_name,
        address = p_address,
        city = p_city,
        state = p_state,
        country = p_country,
        is_main_branch = p_is_main,
        admin_email = p_admin_email,
        updated_at = NOW()
    WHERE id = p_branch_id;


    RETURN QUERY SELECT * FROM public.school_branches WHERE id = p_branch_id;
END;
$$;

-- RPC: Delete School Branch
CREATE OR REPLACE FUNCTION public.delete_school_branch(p_branch_id BIGINT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    DELETE FROM public.school_branches WHERE id = p_branch_id;
END;
$$;

-- RPC: Complete Branch Onboarding Step
CREATE OR REPLACE FUNCTION public.complete_branch_step()
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    -- Finalize institutional identity
    UPDATE public.school_admin_profiles 
    SET onboarding_step = 'completed'
    WHERE user_id = auth.uid();
    
    UPDATE public.profiles
    SET profile_completed = true
    WHERE id = auth.uid();
END;
$$;

-- RPC: Update School Plan & Progress Onboarding
CREATE OR REPLACE FUNCTION public.update_school_plan(p_plan_id TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    UPDATE public.school_admin_profiles SET
        base_plan_id = p_plan_id,
        onboarding_step = 'branches'
    WHERE user_id = auth.uid();
END;
$$;

-- RPC: Verify and Link Branch Admin
CREATE OR REPLACE FUNCTION public.verify_and_link_branch_admin(p_invitation_code TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_branch_id BIGINT;
BEGIN
    SELECT id INTO v_branch_id 
    FROM public.school_branches 
    WHERE access_key = p_invitation_code 
      AND (status = 'Active' OR status = 'Pending');

    IF v_branch_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'The Access Key provided is invalid, expired, or not authorized for this identity.');
    END IF;

    -- Update branch status to Active (Linked)
    UPDATE public.school_branches SET status = 'Active' WHERE id = v_branch_id;

    UPDATE public.profiles SET
        branch_id = v_branch_id,
        role = 'School Administration',
        profile_completed = true
    WHERE id = auth.uid();

    -- Ensure specialized profile exists
    INSERT INTO public.school_admin_profiles (user_id, onboarding_step)
    VALUES (auth.uid(), 'completed')
    ON CONFLICT (user_id) DO UPDATE SET onboarding_step = 'completed';

    RETURN jsonb_build_object('success', true, 'branch_id', v_branch_id);
END;
$$;

-- Parent Portal RPCs
CREATE OR REPLACE FUNCTION public.get_parent_dashboard_stats()
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    v_total INT;
    v_pending INT;
    v_approved INT;
BEGIN
    SELECT count(*) INTO v_total FROM public.admissions WHERE parent_id = auth.uid();
    SELECT count(*) INTO v_pending FROM public.admissions WHERE parent_id = auth.uid() AND status NOT IN ('Approved', 'Verified', 'Enrolled');
    SELECT count(*) INTO v_approved FROM public.admissions WHERE parent_id = auth.uid() AND status IN ('Approved', 'Verified', 'Enrolled');
    
    RETURN jsonb_build_object(
        'total_applications', v_total,
        'pending_applications', v_pending,
        'approved_applications', v_approved
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_my_messages()
RETURNS SETOF public.communications LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY 
    SELECT * FROM public.communications 
    WHERE recipient_role = 'Parent/Guardian'
    OR recipient_id = auth.uid()
    ORDER BY sent_at DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_my_enquiries()
RETURNS SETOF public.admissions LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY
    SELECT * FROM public.admissions
    WHERE parent_id = auth.uid()
    OR (parent_email IS NOT NULL AND parent_email = (SELECT email FROM public.profiles WHERE id = auth.uid()))
    ORDER BY updated_at DESC;
END;
$$;

